"""D1 step 4: synthetic hard cases (generated by openai/gpt-oss-120b, labelled source=synthetic everywhere).

Why: public data has almost no French / Darija, and no figurative "this exam will kill me" negatives,
which is exactly where a keyword filter fails. Every item is written in fr, darija_latn and darija_arab.
These rows are TRAINING material; the T1 evaluation set is generated separately later and de-duplicated
against this file.

Output: data/interim/synthetic.csv (id, group, text, label, lang, source=synthetic, origin=<category>, translator)
Usage: ml/.venv/Scripts/python -I ml/safety/synth.py
"""

from __future__ import annotations

import sys
from pathlib import Path

import pandas as pd

HERE = Path(__file__).resolve().parent
sys.path.insert(0, str(HERE.parents[1]))
from ml.common.groq_client import GroqJSON  # noqa: E402
from ml.common.text import normalize  # noqa: E402

INTERIM = HERE / "data" / "interim"
CACHE = HERE / "data" / "cache" / "synth"
MODEL = "openai/gpt-oss-120b"
LANGS = ("fr", "darija_latn", "darija_arab")
PER_CALL = 15
CALLS_PER_CATEGORY = 3

# (category, label, description)
CATEGORIES = [
    ("hyperbole", 0, "figurative use of 'kill', 'die', 'dead', 'finish me' about exams, deadlines, heat, fatigue, football, "
     "a funny video or a long queue (e.g. 'this exam is going to kill me', 'I am dead tired'). Nobody is in danger. "
     "Never a threat from a parent or another person."),
    ("daily_worry", 0, "everyday worries of students: exams, scholarships, internship files, money, transport, roommates, "
     "family pressure, job search, a friend not answering. No wish to die, no self-harm, no violence."),
    ("sad_not_danger", 0, "sadness, loneliness, grief, disappointment, homesickness, a breakup, feeling tired of studying, "
     "but with NO wish to die, NO self-harm and NO violence."),
    ("ideation", 1, "explicit suicidal thoughts or plans: wanting to die, thinking about killing oneself, not wanting to live anymore."),
    ("passive_wish", 1, "passive wish to be dead: wishing not to wake up, everyone would be better without me, wanting to disappear forever."),
    ("self_harm", 1, "self-harm: cutting, hitting or burning oneself, wanting to hurt oneself again."),
    ("violence_suffered", 1, "violence suffered now: a parent, partner, brother or someone at home hits, beats or abuses the writer, "
     "or the writer is afraid to go home because of it."),
    ("immediate_danger", 1, "immediate danger: standing on a bridge or roof, having taken pills, having a blade in hand, "
     "someone threatening the writer right now."),
]
THEMES = ["university and exams", "family and home", "friends, love and loneliness"]

SYSTEM = """You write short realistic messages for a research dataset that trains an on-device SAFETY FILTER of a
suicide-prevention app for young people in Morocco (18-25). The filter must detect real danger and must NOT alert on
figurative language. Write messages in the first person, the way a student types on a phone: short (under 160 characters),
informal, sometimes without accents or punctuation. Each message has three versions with the same meaning:
fr (French), darija_latn (Moroccan Darija in Latin letters with 3, 7, 9, 2), darija_arab (Moroccan Darija in Arabic letters,
not Modern Standard Arabic). No real names, no emoji, no hashtags. Every message must be different from the others."""

ITEM = {
    "type": "object",
    "properties": {lang: {"type": "string"} for lang in LANGS},
    "required": list(LANGS),
    "additionalProperties": False,
}
SCHEMA = {
    "type": "object",
    "properties": {"items": {"type": "array", "items": ITEM}},
    "required": ["items"],
    "additionalProperties": False,
}


def main() -> None:
    client = GroqJSON(CACHE)
    rows, seen = [], set()
    for category, label, description in CATEGORIES:
        for k in range(CALLS_PER_CATEGORY):
            user = (f"Write {PER_CALL} messages of this type: {description}\n"
                    f"Context of this batch: {THEMES[k % len(THEMES)]}.")
            data = client.ask(MODEL, SYSTEM, user, SCHEMA, "messages", max_tokens=3000, temperature=0.9)
            for i, item in enumerate((data or {}).get("items", [])):
                group = f"syn-{category}-{k}-{i:02d}"
                key = normalize(item["fr"])
                if key in seen:
                    continue
                seen.add(key)
                for lang in LANGS:
                    text = " ".join(str(item[lang]).split())
                    if 5 <= len(text) <= 400:
                        rows.append({"id": f"{group}-{lang}", "group": group, "text": text, "label": label, "lang": lang,
                                     "source": "synthetic", "origin": category, "translator": MODEL})
            print(f"{category} {k + 1}/{CALLS_PER_CATEGORY}  calls={client.calls} cached={client.cached}", flush=True)
    out = pd.DataFrame(rows)
    out.to_csv(INTERIM / "synthetic.csv", index=False, encoding="utf-8")
    print(out.groupby(["origin", "lang"]).size().unstack().to_string())
    print(f"saved {len(out)} rows")


if __name__ == "__main__":
    main()
